#include <stdio.h>

int main(void) {
    // 같은 창고의 칸별 재고예요.
    int bins[] = {2, 4, 6};
    // 이 줄을 고쳐 전체 저장 크기를 한 원소 크기로 나눠 칸 수를 구하세요.
