#include <stdio.h>

int main(void) {
    // 같은 창고의 칸별 재고예요.
    int bins[] = {2, 4, 6};
    // 같은 사용 개수와 합계를 준비해요.
    int count = 3;
    int total = 0;
    int index = 0;
    // 이 주석 아래에 index가 count보다 작을 동안 현재 칸을 더하고 index를 1 올리는 while 문을 쓰세요.
    // while은 조건만 검사해요. 위치를 옮기는 줄을 빼면 반복이 끝나지 않아요.
    while (index < count) {
        total = total + bins[index];
        index = index + 1;
    }
    printf("%d", total);
    return 0;
}

